// Auto-generated from NASA/JPL PIA02031 MOLA topography (public domain) by scripts/build-mola-height.py + bake step
// Shape = real MOLA elevation per biome window; vertical exaggerated for gameplay.
export const PATCH_N = 56;
export const PATCH_ORDER = ["arcadia", "valles", "olympus", "polar", "storm"];
export const PATCH_IDX = {"arcadia": 0, "valles": 1, "olympus": 2, "polar": 3, "storm": 4};
export const PATCH_RELIEF = {"arcadia": 42, "valles": 110, "olympus": 135, "polar": 55, "storm": 38};
export const PATCH_MIN_E = {"arcadia": -5336, "valles": -7500, "olympus": -7500, "polar": -1150, "storm": -2499};
export const PATCH_MAX_E = {"arcadia": 0, "valles": 9000, "olympus": 9000, "polar": 8149, "storm": 4784};
export const PATCH_B64 = "";
export function decodePatches(){
  const N = PATCH_N;
  const bin = atob(PATCH_B64);
  const bytes = new Uint8Array(bin.length);
  for(let i=0;i<bin.length;i++) bytes[i]=bin.charCodeAt(i);
  // 3x3 smoothed planes per patch
  const out = [];
  for(let p=0;p<PATCH_ORDER.length;p++){
    const src = (i,j)=> bytes[p*N*N + Math.max(0,Math.min(N-1,j))*N + Math.max(0,Math.min(N-1,i))];
    const plane = new Float32Array(N*N);
    for(let j=0;j<N;j++) for(let i=0;i<N;i++){
      let s=0; for(let dj=-1;dj<=1;dj++) for(let di=-1;di<=1;di++) s+=src(i+di,j+dj);
      plane[j*N+i]=s/9/255;
    }
    out.push(plane);
  }
  return out;
}
